      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Zile AS (\n    SELECT DATEFROMPARTS(@Anul, @Luna, 1) AS Data\n    UNION ALL\n    SELECT DATEADD(DAY, 1, Data)\n    FROM Zile\n    WHERE MONTH(DATEADD(DAY, 1, Data)) = @Luna\n)\nSELECT COUNT(*) AS ZileLucratoare\nFROM Zile\nWHERE DATENAME(WEEKDAY, Data) NOT IN (&#39;Saturday&#39;, &#39;Sunday&#39;)\nOPTION (MAXRECURSION 40);\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;ZileLucratoare&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false}&lt;/ActionData&gt;
